insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_dance2_v1'
from (values
('117.307.c.1.A',3,'During a traveling combination, each dancer adjusts her path so the group keeps even spacing. This shows what skill?','["Spatial awareness within a group", "Costume matching", "Script memorization", "Music mixing"]'::jsonb,0,'Dancers monitor their space in a group.','original'),
('117.307.c.1.A',3,'A dancer closes her eyes and still holds a balance because she senses where her body is. This demonstrates what?','["Choreographic notation", "Kinesthetic awareness", "Stage lighting", "Audience etiquette"]'::jsonb,1,'Kinesthetic awareness is the sense of body position.','original'),
('117.307.c.1.B',3,'Which practice best protects a dancer''s joints on a hard floor?','["Jumping without a warm-up", "Landing on straight, locked knees", "Landing jumps through the toes, ball and heel with bent knees", "Skipping the plie"]'::jsonb,2,'Soft, controlled landings absorb impact.','original'),
('117.307.c.1.B',3,'A dancer feels sharp pain in her ankle during class. What should she do?','["Hide it", "Dance harder", "Push through the pain", "Stop, tell the teacher and rest the injury"]'::jsonb,3,'Pain signals injury and needs attention.','original'),
('117.307.c.1.C',3,'A dancer correctly names a movement in French ballet terminology and performs it. She is showing knowledge of what?','["Dance vocabulary", "Lighting design", "Set design", "Box office rules"]'::jsonb,0,'Technical vocabulary labels movements.','original'),
('117.307.c.1.C',3,'What distinguishes tap from other dance genres?','["Use of pointe shoes", "Rhythms created by metal plates on the shoes", "Only partner lifts", "Silent movement only"]'::jsonb,1,'Tap uses sound from shoes as percussion.','original'),
('117.307.c.1.D',3,'A dancer interprets the movement of waves in an ocean through flowing, rising and falling motion. This is an example of what?','["Reading a score", "Counting beats", "Interpreting details of movement in a natural environment", "Costume fitting"]'::jsonb,2,'Nature can inspire movement.','original'),
('117.307.c.1.D',3,'Which constructed environment could inspire sharp, mechanical movement?','["A quiet meadow", "A drifting cloud", "A gentle stream", "A busy factory assembly line"]'::jsonb,3,'Machines suggest precise, repeating motion.','original'),
('117.307.c.2.A',3,'A teacher reminds a dancer to engage her core and keep her ribs over her hips. She is working on what?','["Proper body alignment", "Lighting cues", "Music selection", "Costume repairs"]'::jsonb,0,'Core engagement supports alignment.','original'),
('117.307.c.2.A',3,'How does poor alignment during turns affect a dancer?','["It improves balance", "It makes turns less stable and can strain the body", "It adds height to jumps", "It prevents fatigue"]'::jsonb,1,'Misalignment hurts stability.','original'),
('117.307.c.2.B',3,'A student performs an original solo she created from her own exploration. This is an example of what?','["Memorizing a drill", "Reading a score", "Performing original movement from the creative process", "Copying a routine"]'::jsonb,2,'Original solos come from creative exploration.','original'),
('117.307.c.2.B',3,'Which step usually comes first in the creative process for a new dance?','["Taking a final bow", "Printing programs", "Selling tickets", "Exploring and improvising movement ideas"]'::jsonb,3,'Exploration generates ideas.','original'),
('117.307.c.2.C',3,'A dancer wants to show anger, so she uses sharp, strong gestures and heavy stomps. She is expanding her ability to do what?','["Express ideas and emotions through movement", "Count beats", "Set the lights", "Warm up"]'::jsonb,0,'Movement qualities convey emotion.','original'),
('117.307.c.2.C',3,'Which pair of movement choices best conveys joy?','["Closed, heavy gestures", "Light, buoyant leaps and open arms", "Hunched, slow steps", "Stillness with a down gaze"]'::jsonb,1,'Open and buoyant movements read as joyful.','original'),
('117.307.c.2.D',3,'A choreographer uses rondo form, returning to the main theme between contrasting sections. This is an example of what?','["A warm-up", "A lighting plot", "An enhanced compositional form", "A costume plot"]'::jsonb,2,'Rondo (ABACA) is a compositional form.','original'),
('117.307.c.2.D',3,'Which choreographic device repeats a movement in exact order, then reverses it?','["Accumulation only", "Unison", "Canon", "Retrograde"]'::jsonb,3,'Retrograde reverses a sequence.','original'),
('117.307.c.3.A',3,'A dancer performs a 32-count combination in 3/4 time without losing the beat. This shows what?','["Rhythmic accuracy in extended movement patterns", "Set design skill", "Stage management", "Costume mastery"]'::jsonb,0,'She keeps accurate rhythm in a long pattern.','original'),
('117.307.c.3.A',3,'In a waltz, how many beats are in each measure?','["2", "3", "4", "6"]'::jsonb,1,'A waltz is in 3/4 time.','original'),
('117.307.c.3.B',3,'A dancer uses a sudden stop followed by a flowing sweep to show contrast. She is demonstrating which element of dance?','["Set", "Ticketing", "Time and energy", "Costume"]'::jsonb,2,'Tempo and force are elements.','original'),
('117.307.c.3.B',3,'Which choice shows effective use of the dance element of space?','["Staying in one spot with the same level", "Hiding behind other dancers", "Facing only one direction", "Using different pathways, directions and levels"]'::jsonb,3,'Space includes pathways, direction and level.','original'),
('117.307.c.3.C',3,'A group performs a dance that moves from a solo to a duet to a full ensemble, building intensity. This shows effective use of what?','["A choreographic process of developing a phrase", "A prop list", "A costume change", "A lighting check"]'::jsonb,0,'Building group size develops the dance.','original'),
('117.307.c.3.C',3,'In choreography, what is the purpose of a transition between sections?','["To stop the dance", "To connect sections smoothly", "To confuse the audience", "To end the music"]'::jsonb,1,'Transitions link sections.','original'),
('117.307.c.3.D',3,'A complete warm-up for dance class begins with what?','["Static stretching cold", "Holding one pose for ten minutes", "Gentle movements that raise body temperature before stretching", "Intense jumps"]'::jsonb,2,'Warm up before stretching or intense work.','original'),
('117.307.c.3.D',3,'Which element of conditioning builds strength needed for lifting and jumping?','["Skipping meals", "Ignoring flexibility", "Sitting still", "Strength training for the legs and core"]'::jsonb,3,'Strength supports dance demands.','original'),
('117.307.c.4.A',3,'A student compares a West African dance with a classical ballet, noting differences in posture, rhythm and purpose. She is doing what?','["Analyzing dances of various cultures", "Memorizing a list", "Mixing music", "Painting a mural"]'::jsonb,0,'Analysis compares features across cultures.','original'),
('117.307.c.4.A',3,'What might analysis of a historical court dance reveal?','["Current fashion", "Social customs and values of its time", "Modern pop lyrics", "Sports statistics"]'::jsonb,1,'Court dance reflects its society.','original'),
('117.307.c.4.B',3,'A student choreographs a short phrase inspired by dances of the Harlem Renaissance. This shows understanding of what?','["A weather pattern", "A math formula", "A historical period", "A recipe"]'::jsonb,2,'Choreography can reflect a period.','original'),
('117.307.c.4.B',3,'To choreograph a phrase in a historical style, a student should first do what?','["Skip the research", "Ignore the style", "Copy a pop song", "Research the movement, music and context of the era"]'::jsonb,3,'Research informs authentic choreography.','original'),
('117.307.c.4.C',3,'A dancer performs choreography in a school musical. This is an example of performing dance in which context?','["Media and content areas such as theater", "A math exam only", "A lab experiment", "No context"]'::jsonb,0,'Dance appears in musicals and other media.','original'),
('117.307.c.4.C',3,'Which of these is a media context where a dancer might perform?','["A cafeteria menu", "A television commercial", "A bus schedule", "A parking lot"]'::jsonb,1,'Dance is used in commercials and films.','original'),
('117.307.c.4.D',3,'A student uses an online archive of videos to study how a folk dance changed over time. She is using technology to do what?','["Hide the dance", "Avoid research", "Interpret historical and cultural dance forms", "Delete footage"]'::jsonb,2,'Archives allow study of dances.','original'),
('117.307.c.4.D',3,'Which technology tool helps document a dance for historical study?','["A stopwatch only", "A ruler", "A thermometer", "Video recording"]'::jsonb,3,'Video preserves choreography.','original'),
('117.307.c.5.A',3,'A student lists that jazz dance often uses syncopated rhythms, isolations and strong energy. She is doing what?','["Identifying characteristics of a dance", "Planning a budget", "Judging a contest", "Selling tickets"]'::jsonb,0,'Characteristics define a genre.','original'),
('117.307.c.5.A',3,'Which characteristic is common in modern dance?','["Strict tap sounds only", "Use of weight, floor work and expression of ideas", "Silent stillness only", "Only partner lifts"]'::jsonb,1,'Modern dance uses weight and floor work.','original'),
('117.307.c.5.B',3,'After watching a performance, a student comments on the dancers'' timing, energy and focus. She is doing what?','["Ignoring the dancers", "Hiding her opinion", "Analyzing performance quality", "Counting seats"]'::jsonb,2,'Analysis uses dance vocabulary.','original'),
('117.307.c.5.B',3,'Which behavior reflects proper etiquette at a dance concert?','["Recording with flash", "Leaving mid-piece loudly", "Calling out to dancers", "Staying seated quietly until the piece ends and then applauding"]'::jsonb,3,'Quiet respect is expected.','original'),
('117.307.c.5.C',3,'A dancer and a poet both use repetition to emphasize an idea. This shows what similarity?','["A shared use of form and expression across content areas", "No similarity", "The same price", "A common costume"]'::jsonb,0,'Arts share forms like repetition.','original'),
('117.307.c.5.C',3,'Which pair shares the idea of rhythm?','["Dance and weather", "Dance and music", "Dance and geography only", "Dance and maps"]'::jsonb,1,'Rhythm links dance and music.','original'),
('117.307.c.5.D',3,'A choreographer uses a free app to build a sound mix for her dance. She is applying technology to do what?','["Avoid music", "Delete her dance", "Support her choreography", "Stop rehearsals"]'::jsonb,2,'Software can create music.','original'),
('117.307.c.5.D',3,'Which technology can help a dancer review her turns?','["A paper map", "A mixing bowl", "A tape measure", "Slow-motion video playback"]'::jsonb,3,'Slow motion shows technical details.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
